  "inlineSchema": "datasource db {\n  provider = \"sqlite\"\n  url      = \"file:./dev.db\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nmodel Person {\n  person_id        Int       @id @default(autoincrement())\n  first_name       String\n  last_name        String\n  fullName         String?\n  maiden_name      String?\n  gender           String // Enforced values: 'Male', 'Female', 'Other', 'Unknown'\n  photoUrl         String?\n  birth_date       DateTime?\n  birth_place      String?\n  death_date       DateTime?\n  death_place      String?\n  burialPlace      String?\n  is_living        Boolean   @default(true)\n  bio              String?\n  ghana_card       String?\n  gps_address      String?\n  phone            String?\n  email            String?\n  currentAddress   String?\n  hometown         String?\n  profession       String?\n  employer         String?\n  church           String?\n  baptismDetails   String?\n  bloodGroup       String? // \"A+\", \"O+\", \"A-\", etc.\n  genotype         String? // \"AA\", \"AS\", \"SS\", \"AC\"\n  educationJson    String? // JSON string\n  documentsJson    String? // JSON string\n  biographyJson    String? // JSON string\n  clan_id          Int?\n  paramountcy_id   Int?\n  sub_stool_id     Int?\n  enstoolment_date DateTime?\n\n  // Direct Parent References\n  fatherId       Int?\n  motherId       Int?\n  father         Person?  @relation(\"FatherToChildren\", fields: [fatherId], references: [person_id])\n  mother         Person?  @relation(\"MotherToChildren\", fields: [motherId], references: [person_id])\n  fatherChildren Person[] @relation(\"FatherToChildren\")\n  motherChildren Person[] @relation(\"MotherToChildren\")\n\n  // Marital Relations\n  marriagesAsSpouse1 Marriage[] @relation(\"Spouse1\")\n  marriagesAsSpouse2 Marriage[] @relation(\"Spouse2\")\n\n  // Relations\n  relationships1 Relationship[] @relation(\"Person1\")\n  relationships2 Relationship[] @relation(\"Person2\")\n  sources        Source[]\n  clan           Clan?          @relation(fields: [clan_id], references: [id])\n  paramountcy    Paramountcy?   @relation(fields: [paramountcy_id], references: [id])\n  sub_stool      SubStool?      @relation(fields: [sub_stool_id], references: [id])\n\n  // Asantehene Dynastic & Succession Fields\n  dynasticOrder  Int?    @unique // legacy – kept for compat\n  dynasticNumber Int?    @unique // canonical field for horizontal peer chain\n  reignStartYear Int?\n  reignEndYear   Int?\n  predecessorId  Int?    @unique\n  successorId    Int?    @unique\n  // KingSuccession – horizontal peer chain (NOT biological parent-child)\n  predecessor    Person? @relation(\"KingSuccession\", fields: [predecessorId], references: [person_id])\n  successor      Person? @relation(\"KingSuccession\")\n}\n\nmodel Marriage {\n  id            Int       @id @default(autoincrement())\n  spouse1Id     Int\n  spouse2Id     Int\n  marriageDate  DateTime?\n  marriagePlace String?\n\n  spouse1 Person @relation(\"Spouse1\", fields: [spouse1Id], references: [person_id], onDelete: Cascade)\n  spouse2 Person @relation(\"Spouse2\", fields: [spouse2Id], references: [person_id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n}\n\nmodel Clan {\n  id          Int      @id @default(autoincrement())\n  name        String   @unique // e.g., Bretuo\n  totem       String? // e.g., The Leopard\n  description String?\n  persons     Person[]\n}\n\nmodel Region {\n  id            Int           @id @default(autoincrement())\n  name          String        @unique // e.g., Ashanti Region\n  paramountcies Paramountcy[]\n}\n\nmodel Paramountcy {\n  id         Int        @id @default(autoincrement())\n  name       String // e.g., Kumasi Traditional Council\n  region_id  Int\n  region     Region     @relation(fields: [region_id], references: [id])\n  sub_stools SubStool[]\n  persons    Person[]\n}\n\nmodel SubStool {\n  id             Int         @id @default(autoincrement())\n  name           String\n  paramountcy_id Int\n  paramountcy    Paramountcy @relation(fields: [paramountcy_id], references: [id])\n  persons        Person[]\n}\n\nmodel Relationship {\n  relationship_id   Int       @id @default(autoincrement())\n  person_id_1       Int\n  person_id_2       Int\n  relationship_type String // Enforced values: 'Parent-Child', 'Spouse', 'Partner', etc.\n  subtype           String // Enforced values: 'Biological', 'Adoptive', 'Step', 'Foster', 'None', etc.\n  category          String    @default(\"PARENT_CHILD\") // Enforced values: 'PARENT_CHILD', 'SIBLING', 'SPOUSE', 'DYNASTIC_SUCCESSOR', 'QUEEN_MOTHER_STOOL_PAIR', 'FEKUO_SUB_STOOL'\n  traditionalRole   String? // e.g., \"Krontihene\", \"16th Asantehene\", \"Asantehemaa\"\n  status            String? // Enforced values: 'Married', 'Divorced', 'Widowed', 'Separated', 'Active'\n  start_date        DateTime?\n  end_date          DateTime?\n  notes             String?\n\n  // Relations mapping\n  person_1 Person @relation(\"Person1\", fields: [person_id_1], references: [person_id], onDelete: Cascade)\n  person_2 Person @relation(\"Person2\", fields: [person_id_2], references: [person_id], onDelete: Cascade)\n\n  // Constraints and Indexes\n  @@unique([person_id_1, person_id_2, category], name: \"person_pair_category_unique\")\n  @@index([person_id_1])\n  @@index([person_id_2])\n}\n\nmodel Source {\n  source_id        Int       @id @default(autoincrement())\n  person_id        Int\n  title            String\n  document_type    String?\n  url              String?\n  publication_date DateTime?\n\n  // Relations mapping\n  person Person @relation(fields: [person_id], references: [person_id], onDelete: Cascade)\n}\n\nmodel User {\n  user_id       Int      @id @default(autoincrement())\n  username      String   @unique\n  email         String?  @unique\n  password_hash String?\n  salt          String?\n  role          String   @default(\"Staff\")\n  google_id     String?  @unique\n  avatar_url    String?\n  created_at    DateTime @default(now())\n}\n\nmodel TraditionalStool {\n  id        Int    @id @default(autoincrement())\n  stoolName String // e.g., \"Amaniampong Silver Stool\", \"Yiadom & Hwedie Stool\"\n  title     String // e.g., \"Mamponhene\", \"Mamponhemaa\", \"Dwabenhene\"\n  town      String // e.g., \"Mampong\", \"Juaben\", \"Koforidua\", \"Ho\"\n  region    String // e.g., \"Ashanti\", \"Eastern\", \"Volta\", \"Bono\"\n  category  String @default(\"REGIONAL_PARAMOUNT\") // \"AMANTOO_FOUNDING\", \"KUMASI_DIVISIONAL\", \"REGIONAL_PARAMOUNT\", \"DIVISIONAL_SUB\", \"GENERAL_GHANA_TRADITIONAL\"\n  rank      String // \"KING\", \"QUEEN_MOTHER_SUPREME\", \"AMANHENE\", \"AMANHEMAA\", \"DIVISIONAL_CHIEF\", \"DIVISIONAL_QUEEN_MOTHER\", \"SUB_CHIEF\", \"SUB_QUEEN_MOTHER\"\n\n  // Current Occupant & Lineage\n  currentOccupant String?\n  clan            String? // e.g., \"Bretuo\", \"Oyoko\", \"Aduana\"\n  palaceName      String? // e.g., \"Amaniampong Palace\"\n  seatLocation    String?\n  enstoolmentDate DateTime?\n  imageUrl        String?\n\n  // Wing / Military / Palace Division (Fekuo)\n  militaryWing String? // e.g., \"Kronti\", \"Nifa\", \"Benkum\", \"Adonten\", \"Gyaase\", \"Ankobea\"\n  notes        String?\n\n  // Parent Stool Relational Link (Supports Hierarchical Councils & Sub-Queen Mothers)\n  parentStoolId Int?\n  parentStool   TraditionalStool?  @relation(\"StoolHierarchy\", fields: [parentStoolId], references: [id])\n  subStools     TraditionalStool[] @relation(\"StoolHierarchy\")\n\n  // Link to Queen Mother counterpart (Direct male-female stool pairing)\n  queenMotherStoolId Int?              @unique\n  queenMotherStool   TraditionalStool? @relation(\"ChiefQueenPair\", fields: [queenMotherStoolId], references: [id])\n  chiefStool         TraditionalStool? @relation(\"ChiefQueenPair\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
